package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type DateRec struct {
	DtId   string
	DtYyyy int64
	DtMm   int64
	DtDd   int64
}

var WsEofFlag string = "N"
var WsLeapFlag string = "N"
var WsQ int64 = 0
var WsR4 int64 = 0
var WsR100 int64 = 0
var WsR400 int64 = 0
var WsMaxDay int64 = 0
var WsValid int64 = 0
var WsBadMonth int64 = 0
var WsBadDay int64 = 0

var dateRec DateRec

var inputLines []string
var inputIndex int
var isInputDone bool

func pow10(n int) int64 {
	var p int64 = 1
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func truncStore(v int64, digits int) int64 {
	mod := pow10(digits)
	// COBOL keeps low-order digits; for positive just modulo
	// For negative, keep sign? Not needed for this program but implement
	if v >= 0 {
		return v % mod
	}
	// for negative, low-order digits with sign
	// e.g., -1234 into 9(2) should be -34? Keep simple: modulo with sign
	av := -v
	av = av % mod
	return -av
}

func formatPic9(v int64, width int) string {
	mod := pow10(width)
	// display low-order digits if overflow
	// handle negative
	var uv int64
	if v < 0 {
		uv = -v
		uv = uv % mod
		// For display of negative, COBOL would show sign; not needed here
		return fmt.Sprintf("%0*d", width, uv)
	}
	uv = v % mod
	return fmt.Sprintf("%0*d", width, uv)
}

func isInputDoneFunc() bool {
	return WsEofFlag == "Y"
}

func isLeap() bool {
	return WsLeapFlag == "Y"
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func parseNumField(s string) int64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	// keep only digits and optional sign; COBOL numeric fields are digits
	// If contains non-digit, try to parse leading
	v, err := strconv.ParseInt(t, 10, 64)
	if err != nil {
		// if parsing fails due to spaces inside, try trimming
		// fallback to 0
		// try to extract digits
		var digits strings.Builder
		for _, ch := range t {
			if ch >= '0' && ch <= '9' {
				digits.WriteRune(ch)
			} else if ch == '-' {
				digits.WriteRune(ch)
			}
		}
		if digits.Len() == 0 {
			return 0
		}
		v2, err2 := strconv.ParseInt(digits.String(), 10, 64)
		if err2 != nil {
			return 0
		}
		return v2
	}
	return v
}

func openDateFile() {
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	// allow long lines
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, 1024*1024)
	for scanner.Scan() {
		line := scanner.Text()
		// Scanner strips \r and \n; need to handle \r leftover
		// Keep as is (without newline)
		inputLines = append(inputLines, line)
	}
	if err := scanner.Err(); err != nil {
		fmt.Fprintf(os.Stderr, "read input.dat: %v\n", err)
		os.Exit(1)
	}
	inputIndex = 0
}

func MAIN_PARA() {
	openDateFile()
	READ_PARA()
	for !isInputDoneFunc() {
		PROCESS_PARA()
	}
	// CLOSE DATE-FILE (no action needed)
	// DISPLAY "VALID: " WS-VALID " BAD MONTH: " WS-BAD-MONTH " BAD DAY: " WS-BAD-DAY
	// WS fields are PIC 99 zero-padded width 2
	line := "VALID: " + formatPic9(WsValid, 2) + " BAD MONTH: " + formatPic9(WsBadMonth, 2) + " BAD DAY: " + formatPic9(WsBadDay, 2)
	fmt.Println(line)
}

func READ_PARA() {
	if inputIndex >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	raw := inputLines[inputIndex]
	inputIndex++
	// pad with spaces to record length 12
	if len(raw) < 12 {
		raw = raw + strings.Repeat(" ", 12-len(raw))
	} else if len(raw) > 12 {
		raw = raw[:12]
	}
	// parse
	dateRec.DtId = raw[0:4]
	dateRec.DtYyyy = truncStore(parseNumField(raw[4:8]), 4)
	dateRec.DtMm = truncStore(parseNumField(raw[8:10]), 2)
	dateRec.DtDd = truncStore(parseNumField(raw[10:12]), 2)
}

func PROCESS_PARA() {
	LEAP_PARA()
	if dateRec.DtMm < 1 || dateRec.DtMm > 12 {
		WsBadMonth = truncStore(WsBadMonth+1, 2)
		line := dateRec.DtId + " BAD MONTH " + formatPic9(dateRec.DtMm, 2)
		fmt.Println(line)
	} else {
		DAYS_PARA()
		if dateRec.DtDd < 1 || dateRec.DtDd > WsMaxDay {
			WsBadDay = truncStore(WsBadDay+1, 2)
			line := dateRec.DtId + " BAD DAY " + formatPic9(dateRec.DtDd, 2) + " MAX " + formatPic9(WsMaxDay, 2)
			fmt.Println(line)
		} else {
			WsValid = truncStore(WsValid+1, 2)
			line := dateRec.DtId + " VALID " + formatPic9(dateRec.DtYyyy, 4) + "-" + formatPic9(dateRec.DtMm, 2) + "-" + formatPic9(dateRec.DtDd, 2)
			fmt.Println(line)
		}
	}
	READ_PARA()
}

func LEAP_PARA() {
	// DIVIDE DT-YYYY BY 4 GIVING WS-Q REMAINDER WS-R4
	// integer divide
	var q int64
	var r int64
	if 4 != 0 {
		q = dateRec.DtYyyy / 4
		r = dateRec.DtYyyy % 4
	}
	WsQ = truncStore(q, 4)
	WsR4 = truncStore(r, 3)
	if 100 != 0 {
		q = dateRec.DtYyyy / 100
		r = dateRec.DtYyyy % 100
	}
	WsQ = truncStore(q, 4)
	WsR100 = truncStore(r, 3)
	if 400 != 0 {
		q = dateRec.DtYyyy / 400
		r = dateRec.DtYyyy % 400
	}
	WsQ = truncStore(q, 4)
	WsR400 = truncStore(r, 3)

	if WsR4 == 0 && (WsR100 != 0 || WsR400 == 0) {
		WsLeapFlag = "Y"
	} else {
		WsLeapFlag = "N"
	}
}

func DAYS_PARA() {
	switch dateRec.DtMm {
	case 2:
		if isLeap() {
			WsMaxDay = 29
		} else {
			WsMaxDay = 28
		}
	case 4, 6, 9, 11:
		WsMaxDay = 30
	default:
		WsMaxDay = 31
	}
}

func main() {
	MAIN_PARA()
}
